289	// ---------------------------------------------------------------------------
290	// verify
291	// ---------------------------------------------------------------------------
292	
293	fn verify(args: &[String]) -> ExitCode {
294	    // verify deliberately shares sign's option grammar through the common
295	    // parser but declares its own, narrower table: --key is the only known
296	    // option, so every sign-only option (--key-id, --key-version, --field)
297	    // is rejected here as unrecognized. Values that fail are never echoed
298	    // (they could be a mistyped secret).
299	    const VERIFY_OPTIONS: &[options::Spec] = &[options::Spec {
300	        name: "--key",
301	        multiplicity: options::Multiplicity::Single,
302	    }];
303	
304	    let parse = (|| -> Result<String, String> {
305	        let occurrences = options::parse(args, VERIFY_OPTIONS)?;
306	        // The parser enforces "at most one --key"; take it if present.
307	        let key = occurrences
308	            .first()
309	            .map(|o| o.value.clone())
310	            .ok_or("missing required option --key")?;
311	        validate_key_hex(&key)?;
312	        Ok(key)
313	    })();
314	
315	    let key_hex = match parse {
316	        Ok(key) => key,
317	        Err(msg) => {
318	            eprintln!("authnote verify: {msg}");
319	            return ExitCode::from(2);
320	        }
321	    };
322	
323	    // Read the whole standard input. It must be one JSON record and nothing
324	    // else; trailing non-whitespace is a malformed invocation, not a mismatch.
325	    let mut input = Vec::new();
326	    if let Err(e) = std::io::stdin().read_to_end(&mut input) {
327	        eprintln!("authnote verify: failed to read standard input: {e}");
328	        return ExitCode::from(2);
329	    }
330	
331	    let outcome = verify_input(&input, &key_hex);
332	    match outcome {
333	        VerifyOutcome::Valid => {
334	            println!("{{\"valid\":true}}");
335	            ExitCode::SUCCESS
336	        }
337	        VerifyOutcome::Mismatch => {
338	            println!("{{\"valid\":false}}");
339	            ExitCode::from(1)
340	        }
341	        VerifyOutcome::Invalid(msg) => {
342	            eprintln!("authnote verify: {msg}");
343	            ExitCode::from(2)
344	        }
345	    }
346	}
347	
348	#[derive(Debug)]
349	enum VerifyOutcome {
350	    Valid,
351	    Mismatch,
352	    Invalid(String),
353	}
354	
355	fn verify_input(input: &[u8], key_hex: &str) -> VerifyOutcome {
356	    let text = match std::str::from_utf8(input) {
357	        Ok(t) => t,
358	        // Still parse to distinguish a structurally invalid record from a
359	        // record whose text merely contains bytes Rust rejects; JSON itself
360	        // forbids raw non-UTF-8, so this is always "corrupt input" here.
361	        Err(_) => return VerifyOutcome::Invalid("input is not valid UTF-8 JSON text".to_string()),
362	    };
363	
364	    let value = match json::parse_single(text) {
365	        Ok(v) => v,
366	        Err(msg) => return VerifyOutcome::Invalid(msg),
367	    };
368	    let record = match record_from_json(&value) {
369	        Ok(r) => r,
370	        Err(msg) => return VerifyOutcome::Invalid(msg),
371	    };
372	
373	    let key_bytes = decode_hex(key_hex).expect("key was validated as hex");
374	    let message = encode_message(&record.key_id, record.key_version, &record.fields);
375	    let mut mac = <Hmac<Sha256> as KeyInit>::new_from_slice(&key_bytes)
376	        .expect("HMAC accepts keys of any length");
377	    mac.update(&message);
378	
379	    let expected_tag = mac.finalize().into_bytes();
380	    let given_tag = &record.tag;
381	
382	    // Both sides are 32 bytes; compare in constant time so a mismatch cannot
383	    // be recovered one byte at a time through timing.
384	    debug_assert_eq!(expected_tag.len(), given_tag.len());
385	    if expected_tag.len() != given_tag.len() {
386	        return VerifyOutcome::Mismatch;
387	    }
388	    let mut diff = 0u8;
389	    for (a, b) in expected_tag.iter().zip(given_tag.iter()) {
390	        diff |= a ^ b;
391	    }
392	    if diff == 0 {
393	        VerifyOutcome::Valid
394	    } else {
395	        VerifyOutcome::Mismatch
396	    }
397	}
