399	/// Decode the tag as exactly 32 bytes of case-insensitive hexadecimal.
400	fn decode_tag(s: &str) -> Result<Vec<u8>, String> {
401	    if s.len() != 64 || !s.bytes().all(|b| b.is_ascii_hexdigit()) {
402	        return Err("tag must be exactly 64 hexadecimal characters (32 bytes)".to_string());
403	    }
404	    decode_hex(s).map_err(|e| format!("tag is not valid hexadecimal: {e}"))
405	}
406	
407	struct AuthRecord {
408	    key_id: String,
409	    key_version: u32,
410	    fields: Vec<String>,
411	    tag: Vec<u8>,
412	}
413	
414	/// Validate the decoded JSON value as exactly one format-1 authentication
415	/// record and pull out the authenticated fields. Structural problems (missing
416	/// members, wrong types, duplicates inside `fields`, ...) are caller errors:
417	/// they must produce exit 2, never a `{"valid":false}` mismatch result.
418	fn record_from_json(value: &json::JsonValue) -> Result<AuthRecord, String> {
419	    let obj = match value {
420	        json::JsonValue::Object(entries) => entries,
421	        _ => return Err("record must be a single JSON object".to_string()),
422	    };
423	
424	    // Require precisely the six documented members, each present exactly once;
425	    // the parser already rejects duplicate member names, and an empty object
426	    // naturally fails the "missing required member" checks below.
427	    let mut format: Option<&json::JsonValue> = None;
428	    let mut algorithm: Option<&json::JsonValue> = None;
429	    let mut key_id: Option<&json::JsonValue> = None;
430	    let mut key_version: Option<&json::JsonValue> = None;
431	    let mut fields: Option<&json::JsonValue> = None;
432	    let mut tag: Option<&json::JsonValue> = None;
433	    for (name, val) in obj {
434	        let slot = match name.as_str() {
435	            "format" => &mut format,
436	            "algorithm" => &mut algorithm,
437	            "key_id" => &mut key_id,
438	            "key_version" => &mut key_version,
439	            "fields" => &mut fields,
440	            "tag" => &mut tag,
441	            // Do not echo the unknown member name: it comes from the input
442	            // record, which error messages must never quote back.
443	            _ => return Err("record contains an unexpected member".to_string()),
444	        };
445	        if slot.is_some() {
446	            // The strict parser rejects duplicates already; keep a defense in
447	            // depth without quoting the member name from the input twice.
448	            return Err("record contains a duplicate member".to_string());
449	        }
450	        *slot = Some(val);
451	    }
452	
453	    // Unsupported format/algorithm must be reported as such explicitly: we do
454	    // not silently fall back to the current rules and compute a result.
455	    let format = format.ok_or("record is missing required member \"format\"")?;
456	    match format {
457	        json::JsonValue::Number(n) if *n == i128::from(FORMAT_VERSION) => {}
458	        json::JsonValue::Number(_) => {
459	            return Err("unsupported record format version; only format 1 is supported".to_string())
460	        }
461	        _ => return Err("member \"format\" must be an integer".to_string()),
462	    }
463	
464	    let algorithm = algorithm.ok_or("record is missing required member \"algorithm\"")?;
465	    match algorithm {
466	        json::JsonValue::String(s) if s == ALGORITHM => {}
467	        json::JsonValue::String(_) => {
468	            return Err(
469	                "unsupported algorithm in record; only HMAC-SHA256 is supported".to_string(),
470	            )
471	        }
472	        _ => return Err("member \"algorithm\" must be a string".to_string()),
473	    }
474	
475	    let key_id = key_id.ok_or("record is missing required member \"key_id\"")?;
476	    let key_id = match key_id {
477	        json::JsonValue::String(s) if !s.is_empty() => s.clone(),
478	        json::JsonValue::String(_) => {
479	            return Err("member \"key_id\" must not be empty".to_string())
480	        }
481	        _ => return Err("member \"key_id\" must be a string".to_string()),
482	    };
483	
484	    let key_version = key_version.ok_or("record is missing required member \"key_version\"")?;
485	    let key_version = match key_version {
486	        json::JsonValue::Number(n) => {
487	            if *n < 1 || *n > i128::from(u32::MAX) {
488	                return Err(
489	                    "member \"key_version\" is outside the supported range 1..=4294967295"
490	                        .to_string(),
491	                );
492	            }
493	            *n as u32
494	        }
495	        _ => return Err("member \"key_version\" must be an integer".to_string()),
496	    };
497	
498	    let fields_val = fields.ok_or("record is missing required member \"fields\"")?;
499	    let fields = match fields_val {
500	        json::JsonValue::Array(items) => {
501	            let mut out = Vec::with_capacity(items.len());
502	            for item in items {
503	                match item {
504	                    json::JsonValue::String(s) => out.push(s.clone()),
505	                    _ => {
506	                        return Err(
507	                            "every element of member \"fields\" must be a string".to_string()
508	                        )
509	                    }
510	                }
511	            }
512	            out
513	        }
514	        _ => return Err("member \"fields\" must be an array of strings".to_string()),
515	    };
516	
517	    let tag_val = tag.ok_or("record is missing required member \"tag\"")?;
518	    let tag = match tag_val {
519	        json::JsonValue::String(s) => decode_tag(s)?,
520	        _ => return Err("member \"tag\" must be a string".to_string()),
521	    };
522	
523	    Ok(AuthRecord {
524	        key_id,
525	        key_version,
526	        fields,
527	        tag,
528	    })
529	}
