986	    /// Build a format-1 record JSON string for the given content, with the
987	    /// correct tag for `key`.
988	    fn record_for(key_hex: &str, key_id: &str, version: u32, fields: &[&str]) -> String {
989	        let tag = sign_tag(key_hex, key_id, version, fields);
990	        let fields_json = fields
991	            .iter()
992	            .map(|f| format!("\"{}\"", json_escape(f)))
993	            .collect::<Vec<_>>()
994	            .join(",");
995	        format!(
996	            "{{\"format\":1,\"algorithm\":\"HMAC-SHA256\",\"key_id\":\"{}\",\"key_version\":{},\"fields\":[{}],\"tag\":\"{}\"}}",
997	            json_escape(key_id),
998	            version,
999	            fields_json,
1000	            tag
1001	        )
1002	    }
